  function letterAlbumUnits(done,lastMission){
    const units=[];
    for(const w of (EMILIA_CONTENT.worlds||[])){
      if(!w.letter||['★','✦'].includes(String(w.letter)))continue;
      const conquered=done.has(w.id),latest=conquered&&w.id===lastMission;
      // El primer mundo enseña cinco vocales: el álbum debe devolver cinco conquistas visibles,
      // no condensarlas en una sola ficha. Se reutilizan únicamente assets ya aprobados.
      if(w.id==='forest_vowels'){
        for(const vowel of ['a','e','i','o','u'])units.push({id:`${w.id}_${vowel}`,worldId:w.id,chapter:Number(w.chapter||1),label:vowel.toUpperCase(),name:`Vocal ${vowel.toUpperCase()}`,done:conquered,latest,art:letterArt(vowel)});
        continue;
      }
      const label=w.id==='forest_rr'?'R·RR':w.letter;
      units.push({id:w.id,worldId:w.id,chapter:Number(w.chapter||1),label,name:w.name,done:conquered,latest,art:w.letterArt||letterArt(w.letter)});
    }
    return units;
  }
  function linguisticGemRows(done){
    const tier=ch=>['diamond','ruby','emerald','amethyst'][Math.max(0,Math.min(3,Number(ch||1)-1))];
    const patternSpeech=label=>{const t=String(label||'');if(t==='R·RR')return'erre y doble erre';if(t==='CH')return'che';if(t==='QU')return'que, qui';if(t==='CE·CI')return'ce, ci';if(t==='GE·GI')return'ge, gi';return t;};
    const letters=letterAlbumUnits(done,'').filter(x=>x.done).map(x=>{const text=String(x.label),single=/^[A-ZÁÉÍÓÚÑ]$/i.test(text);return{text,kind:/^[AEIOU]$/i.test(text)?'vowel':(single?'letterName':'instruction'),say:single?text:patternSpeech(text),tier:tier(x.chapter)};}).slice(-12);
    const syllables=[];
    for(const m of (EMILIA_CONTENT.missions||[]).slice().sort((a,b)=>(a.order||0)-(b.order||0))){if(!done.has(m.id))continue;const w=worldFor(m.id),t=tier(w&&w.chapter);for(const a of (m.activities||[])){if(a.type!=='syllableTrail')continue;for(const it of (a.items||[])){const key=String(it).toLocaleLowerCase('es');if(!syllables.some(x=>x.text===key))syllables.push({text:key,kind:/^[aeiouáéíóú]$/i.test(key)?'vowel':'syllable',tier:t});}}}
    const words=(EMILIA_CONTENT.writingLadders||[]).filter(x=>done.has(x.mission)).map(x=>{const w=worldFor(x.mission);return{text:String(x.word).toLocaleLowerCase('es'),kind:'word',tier:tier(w&&w.chapter)};}).slice(-12);
    return[{title:'Letras',items:letters},{title:'Sílabas',items:syllables.slice(-15)},{title:'Palabras',items:words}].filter(r=>r.items.length);
  }
  function linguisticGemMarkup(rows){
    return rows.map(row=>`<div class="ling-gem-row"><div class="ling-gem-row-title">${esc(row.title)}</div><div class="ling-gem-strip">${row.items.map(x=>`<button class="ling-gem crystal-${x.tier} ${x.kind==='word'?'word-gem':''}" data-say="${esc(x.say||x.text)}" data-kind="${esc(x.kind)}" aria-label="Escuchar ${esc(x.text)}"><span class="ling-crystal" aria-hidden="true"><i></i><i></i></span><strong>${esc(x.text)}</strong></button>`).join('')}</div></div>`).join('');
  }
