    set(`<main class="screen gate"><div class="screen-inner"><section class="card gate-card"><div class="eyebrow">Zona adulta</div><h1 class="h2 gate-title">Una comprobación rápida</h1><p class="copy muted">Aquí están el progreso, las recomendaciones y las copias de seguridad.</p><div class="gate-math">${a} + ${b} = ?</div><input class="gate-input" id="gateInput" inputmode="numeric" aria-label="Respuesta"><div class="gate-actions"><button class="btn btn-primary" id="gateOk">Entrar</button><button class="btn btn-secondary" id="gateBack">Volver</button></div></section></div></main>`);
    document.getElementById('gateBack').onclick=()=>EmiliaApp.go('home');document.getElementById('gateOk').onclick=()=>{if(parseInt(document.getElementById('gateInput').value,10)===window.__adultAnswer)EmiliaApp.go('adult');else EmiliaApp.toast('La respuesta no coincide.');};
